  "settings.agentCaps.title": "Agent capabilities",
  "settings.agentCaps.desc":
    "Switches for the capabilities we ported from Codex: project instructions (AGENTS.md) and the image viewer tool. Changes apply to the next turn.",
  "settings.agentCaps.instructions.title": "Project instructions (AGENTS.md)",
  "settings.agentCaps.instructions.desc":
    "Walks up from the workspace to the project root (the directory holding .git) and injects every AGENTS.md it finds — so the agent knows how this project runs tests and which package manager to use. AGENTS.override.md wins in the same directory; user-level instructions live in AGENTS.md inside the data directory.",
  "settings.agentCaps.instructions.enabled": "Enable project instructions",
  "settings.agentCaps.instructions.limit": "Size limit",
  "settings.agentCaps.instructions.files": "Loaded this time",
  "settings.agentCaps.instructions.noFiles":
    "No AGENTS.md in this workspace. Write one at the project root and the agent will follow the project's own conventions.",
  "settings.agentCaps.instructions.noWorkspace": "No workspace set yet",
  "settings.agentCaps.instructions.truncated": "Content exceeded the limit and was truncated",
  "settings.agentCaps.instructions.userFile": "Global instructions file",
  "settings.agentCaps.instructions.source.user": "Global",
  "settings.agentCaps.instructions.source.project": "Project",
  "settings.agentCaps.vision.title": "Image viewer (view_image)",
  "settings.agentCaps.vision.desc":
    "Lets the agent attach a local image to the conversation (screenshots, mockups, generated results). Only vision models accept image blocks — text-only servers reject them — so this defaults to auto-detection by model name.",
  "settings.agentCaps.vision.mode": "Mode",
  "settings.agentCaps.vision.mode.auto": "auto (detect by model)",
  "settings.agentCaps.vision.mode.on": "on (force enable)",
  "settings.agentCaps.vision.mode.off": "off (disable)",
  "settings.agentCaps.hooks.title": "Lifecycle hooks",
  "settings.agentCaps.hooks.desc":
    "Codex-style SessionStart / UserPromptSubmit: run your own script when a session starts or right before a prompt is submitted; its output is injected as context, and it can block the turn. Hooks are read from this setting only — files inside the workspace are never executed (the agent can edit those, which would be an RCE vector).",
  "settings.agentCaps.hooks.config": "Config (JSON array)",
  "settings.agentCaps.hooks.placeholder":
    "[{\"event\":\"user_prompt_submit\",\"command\":\"scripts/context.sh\",\"timeoutMs\":5000}]",
  "settings.agentCaps.hooks.hint":
    "The event JSON arrives on stdin (jq / python both fine) and the event name is in OMNI_HOOK_EVENT. Plain stdout becomes context; JSON stdout is read as {\"decision\":\"block\",\"reason\":\"…\"} or {\"context\":\"…\"}. Events: {events}.",
  "settings.agentCaps.notify.title": "External notification hook",
  "settings.agentCaps.notify.desc":
    "Codex-style notify: when a turn finishes, an approval is needed or an automation ends, the event JSON is handed to your own command — wire it into desktop notifications, phone push or CI hooks.",
  "settings.agentCaps.notify.command": "Command",
  "settings.agentCaps.notify.placeholder": "e.g. notify-send OmniStudio",
  "settings.agentCaps.notify.hint":
    "The event JSON is passed as the last argument ($1 in a script) and also set as OMNI_NOTIFY_PAYLOAD. Leave empty to disable.",
  "settings.agentCaps.notify.on": "enabled",
  "settings.agentCaps.sandbox.title": "Command sandbox",
  "settings.agentCaps.sandbox.desc":
    "Runs the shell commands the agent issues inside the OS sandbox. workspace-write keeps writes inside the workspace, temp directories and authorized folders; read-only blocks writes everywhere except temp directories (test runners and compilers need TMPDIR). Both modes also deny reads of credential paths such as ~/.ssh. The permission gate covers tools; the sandbox covers a bare command line.",
  "settings.agentCaps.sandbox.mode": "Mode",
  "settings.agentCaps.sandbox.mode.off": "off (no sandbox)",
  "settings.agentCaps.sandbox.mode.workspaceWrite": "workspace-write (writes in workspace only)",
  "settings.agentCaps.sandbox.mode.readOnly": "read-only (no writes anywhere)",
  "settings.agentCaps.sandbox.escalation":
    "When the sandbox blocks a command, you get asked whether to retry it without the sandbox (ask in smart / manual, deny by default in auto / strict). To allow it automatically, add a sandbox_escalation → allow rule under Agent permissions.",
  "settings.agentCaps.sandbox.unsupported": "No sandbox implementation for this platform ({platform}) yet — commands still run unsandboxed.",
  "settings.agentCaps.sandbox.backend": "Backend: {backend} (Seatbelt on macOS, bubblewrap on Linux)",
  "settings.agentCaps.sandbox.noBwrap":
    "The Linux sandbox needs bubblewrap: no usable bwrap here (not installed, or unprivileged user namespaces are blocked in this container), so commands still run unsandboxed. Install: apt install bubblewrap / dnf install bubblewrap",
  "settings.agentCaps.sandbox.landlock":
    "Landlock (Linux kernel-level sandbox): rules come from the policy generator, and the native helper is compiled from source on first use (needs cc, kernel 5.13+); when that is not possible it honestly falls back to bubblewrap. Now: {note}",
  "settings.agentCaps.sandbox.network": "Allow network access",
  "settings.agentCaps.sandbox.networkHint": "Turning this off blocks curl and package installs (Codex defaults to no network); local workflows usually want it on.",
  "settings.agentCaps.snapshots.title": "Turn snapshots (undo a turn)",
  "settings.agentCaps.snapshots.desc":
    "Before each turn the agent commits the workspace state into a shadow git repo outside your project. If something goes wrong, undo it from the message — files edited or created during that turn are restored or removed. Your own .git is never touched, and build output such as node_modules stays out of snapshots.",
  "settings.agentCaps.snapshots.status": "Current workspace",
  "settings.agentCaps.snapshots.disk": "Shadow repo size",
  "settings.agentCaps.snapshots.diskHint": "Compacted automatically past {threshold}MB (git gc); you can also clean up now.",
  "settings.agentCaps.snapshots.gc": "Clean up now",
  "settings.agentCaps.snapshots.gcDone": "Compacted: {before} → {after}.",
  "settings.agentCaps.snapshots.gcSkipped": "Nothing to compact this time.",
  "settings.agentCaps.snapshots.turns": "{count} turn snapshot(s) recorded",
  "settings.agentCaps.snapshots.noGit": "git is not installed — snapshots unavailable",
  "settings.agentCaps.vision.current": "Current model",
  "settings.agentCaps.vision.available": "Available",
  "settings.agentCaps.vision.unavailable": "Not enabled (the current model does not look multimodal)",
  "settings.permissions.title": "Agent permissions",
  "agent.approval.desc":
    "Choose which actions the agent may take without asking. smart only gates dangerous ones (rm -rf, sudo, git push, outside the workspace); manual asks for every tool with side effects; auto allows everything; strict denies everything.",
