  "agent.slash.init.prompt":
    "Analyze this project and write an AGENTS.md at the project root: build/test/lint commands, directory layout and conventions, and things to watch out for when editing. If AGENTS.md already exists, read it first and fill in what is missing instead of rewriting it.",
  "agent.slash.doctor.prompt":
    "Use the omni-doctor skill to diagnose an OmniStudio runtime failure: call read_skill to load its body first, then gather evidence the way it describes — `omi status`, `omi logs --level error -v`, `omi server logs` (they read the files on disk even when the app is down), and `bun run --cwd apps/studio scripts/omni-diag.ts` when the workspace is this repo. Every conclusion must point at a log line, a database row, or a command output. End with concrete fix steps; stay read-only unless you say what you are about to write.",
  "agent.slash.doctor.symptom": "Symptom: ",
