  "benchmark.cacheCompare": "Cache hit comparison",
  "benchmark.cacheCompare.reuse": "server reused {percent}% of the input",
  "benchmark.cacheCompare.hint": "Multiplier = cold TTFT ÷ hit TTFT; the larger it is, the more prefix caching buys you. Near ×1 means the server never hit the cache (per-slot KV caches, something that changes in every prefix, or caching disabled in the engine).",
  "benchmark.col.cache": "Cache",
  "benchmark.summaryBasis": "Averages / bests come from the “{basis}” pass (cold and hit are different operating points; blending them means nothing)",
  "benchmark.note.noCacheGain": "{ctx}: a full hit is only {speedup}× faster than cold — the server is not reusing any prefix cache. Usual suspects: per-slot KV caches, something that changes in every prefix (timestamps / session ids), or an engine with caching turned off.",
