const DICTS: Record<UILang, Record<string, string>> = { zh, en };

/** 翻译：zh 缺 key 回落 en 再回落 key 本身；params 做 {name} 简单插值。 */
export function translate(lang: UILang, key: string, params?: Record<string, string>): string {
  let text = DICTS[lang]?.[key] ?? DICTS.en[key] ?? key;
  if (params) {
    for (const [name, value] of Object.entries(params)) {
      text = text.split(`{${name}}`).join(value);
    }
  }
  return text;
}

/**
 * 词条缺失时返回 `undefined`（而不是回退成 key 本身）。
 *
 * `translate` 的约定是"缺词条就把 key 原样返回"，方便一眼看出漏翻；
 * 但有些地方需要的是"有词条用词条、没有就用数据自带的那份"（如模型档案的英文说明），
 * 拿 key 当结果会把界面写成 `modelProfile.lightonocr.description`。
 */
export function translateOptional(
  lang: UILang,
  key: string,
  params?: Record<string, string>,
): string | undefined {
  const text = DICTS[lang]?.[key] ?? DICTS.en[key];
  if (text === undefined) return undefined;
  if (!params) return text;
  let out = text;
  for (const [name, value] of Object.entries(params)) out = out.split(`{${name}}`).join(value);
  return out;
}

export const DEFAULT_LANG: UILang = "zh";

export const LANGS: { value: UILang; label: string }[] = [
  { value: "zh", label: "中文" },
  { value: "en", label: "English" },
];